CREATE FUNCTION public.enlazar_socio(p_token text,p_dispositivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.socios; BEGIN IF auth.uid() IS NULL OR length(p_dispositivo)<16 THEN RAISE EXCEPTION 'No autorizado'; END IF; IF public.has_club_role('directiva') OR public.has_club_role('negocio') THEN RAISE EXCEPTION 'Cierra tu sesión antes de activar'; END IF; SELECT * INTO s FROM public.socios WHERE token_invitacion=p_token AND estado<>'desactivada' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Enlace no válido'; END IF; DELETE FROM public.profiles WHERE socio_id=s.id AND id<>auth.uid(); INSERT INTO public.profiles(id,socio_id,dispositivo_id) VALUES(auth.uid(),s.id,p_dispositivo) ON CONFLICT(id) DO UPDATE SET socio_id=excluded.socio_id,dispositivo_id=excluded.dispositivo_id,patrocinador_id=NULL; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'socia') ON CONFLICT(user_id) DO UPDATE SET role=excluded.role; UPDATE public.socios SET estado='activa',mayor_de_edad=true,consentimiento_at=now(),fecha_activacion=now(),cambio_dispositivo=cambio_dispositivo OR (dispositivo_id IS NOT NULL AND dispositivo_id<>p_dispositivo),dispositivo_id=p_dispositivo WHERE id=s.id; RETURN s.id; END $$;
CREATE FUNCTION public.entrar_negocio(p_pin text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; a public.pin_intentos; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'No autorizado'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RETURN NULL; END IF; INSERT INTO public.pin_intentos(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.pin_intentos WHERE user_id=auth.uid() FOR UPDATE; IF a.ventana<now()-interval '15 minutes' THEN UPDATE public.pin_intentos SET intentos=0,ventana=now() WHERE user_id=auth.uid(); a.intentos:=0; END IF; IF a.intentos>=5 THEN RETURN NULL; END IF; UPDATE public.pin_intentos SET intentos=intentos+1 WHERE user_id=auth.uid(); SELECT id INTO n FROM public.patrocinadores WHERE activo AND pin_hash=extensions.crypt(p_pin,pin_hash) LIMIT 1; IF n IS NULL THEN RETURN NULL; END IF; INSERT INTO public.profiles(id,patrocinador_id) VALUES(auth.uid(),n); INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'negocio'); RETURN n; END $$;
CREATE FUNCTION public.identificar_socio(p_numero bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.socios; BEGIN IF public.mi_patrocinador() IS NULL AND NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; SELECT * INTO s FROM public.socios WHERE numero_socio=p_numero AND estado='activa'; IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('id',s.id,'nombre',s.nombre,'numeroSocio',s.numero_socio,'repite',EXISTS(SELECT 1 FROM public.visitas WHERE socio_id=s.id AND patrocinador_id=public.mi_patrocinador() AND NOT anulada),'yaHoy',EXISTS(SELECT 1 FROM public.visitas WHERE socio_id=s.id AND patrocinador_id=public.mi_patrocinador() AND fecha=(now() AT TIME ZONE 'Europe/Madrid')::date AND NOT anulada)); END $$;
CREATE FUNCTION public.marcar_apertura() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.socios SET ultima_apertura=now() WHERE id=public.mi_socio() $$;
CREATE FUNCTION public.crear_patrocinador(p_nombre text,p_categoria text,p_direccion text,p_logo text,p_pin text,p_titulo text,p_descripcion text,p_condiciones text,p_importe numeric DEFAULT 0) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF p_pin !~ '^[0-9]{4}$' OR length(trim(p_nombre))=0 OR length(p_nombre)>200 OR length(p_titulo)=0 OR p_importe<0 THEN RAISE EXCEPTION 'Datos no válidos'; END IF; PERFORM pg_advisory_xact_lock(202627); IF EXISTS(SELECT 1 FROM public.patrocinadores WHERE pin_hash=extensions.crypt(p_pin,pin_hash)) THEN RETURN NULL; END IF; INSERT INTO public.patrocinadores(nombre,categoria,direccion,logo_url,pin_hash,importe_patrocinio) VALUES(p_nombre,p_categoria,p_direccion,p_logo,extensions.crypt(p_pin,extensions.gen_salt('bf')),p_importe) RETURNING id INTO n; INSERT INTO public.ventajas(patrocinador_id,titulo,descripcion,condiciones,destacado) VALUES(n,p_titulo,p_descripcion,p_condiciones,'Socia/o'); RETURN n; END $$;
CREATE FUNCTION public.stats_patrocinador(p_patrocinador_id uuid,p_periodo text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE desde timestamptz; fin timestamptz:=now(); paso interval; ini timestamptz; serie jsonb; resultado jsonb; gasto numeric; cuota numeric; BEGIN IF NOT public.has_club_role('directiva') AND p_patrocinador_id IS DISTINCT FROM public.mi_patrocinador() THEN RAISE EXCEPTION 'No autorizado'; END IF; IF auth.uid() IS NULL THEN RAISE EXCEPTION 'No autorizado'; END IF; IF p_periodo='mes' THEN desde:=date_trunc('month',now() AT TIME ZONE 'Europe/Madrid') AT TIME ZONE 'Europe/Madrid'; paso:=interval '7 days'; ELSIF p_periodo='90d' THEN desde:=now()-interval '90 days'; paso:=interval '7 days'; ELSIF p_periodo='temporada' THEN desde:='2026-09-01T00:00:00+02'; paso:=interval '1 month'; ELSE RAISE EXCEPTION 'Periodo no válido'; END IF;
SELECT jsonb_build_object('visitas',count(*),'total_visitas',count(*),'nuevas',count(*) FILTER(WHERE tipo_cliente='nueva'),'nuevas_verificadas',count(*) FILTER(WHERE tipo_cliente='nueva' AND verificada),'nuevas_declaradas',count(*) FILTER(WHERE tipo_cliente='nueva' AND NOT verificada),'verificadas',count(*) FILTER(WHERE verificada),'declaradas',count(*) FILTER(WHERE NOT verificada),'repiten',count(*) FILTER(WHERE repite_via_club),'pct_nuevas',CASE WHEN count(*)=0 THEN 0 ELSE round(100.0*count(*) FILTER(WHERE tipo_cliente='nueva')/count(*)) END,'con_importe',count(tramo_gasto),'gasto_nuevas_estimado',coalesce(sum(CASE tramo_gasto WHEN 'lt20' THEN 10 WHEN '20_50' THEN 35 WHEN '50_100' THEN 75 WHEN 'gt100' THEN 120 ELSE 0 END) FILTER(WHERE tipo_cliente='nueva'),0),'gasto_total_estimado',coalesce(sum(CASE tramo_gasto WHEN 'lt20' THEN 10 WHEN '20_50' THEN 35 WHEN '50_100' THEN 75 WHEN 'gt100' THEN 120 ELSE 0 END),0)) INTO resultado FROM public.visitas WHERE patrocinador_id=p_patrocinador_id AND NOT anulada AND fecha_hora>=desde AND fecha_hora<=fin;
SELECT importe_patrocinio INTO cuota FROM public.patrocinadores WHERE id=p_patrocinador_id; gasto:=(resultado->>'gasto_total_estimado')::numeric;
SELECT coalesce(jsonb_agg(jsonb_build_object('label',CASE WHEN p_periodo='temporada' THEN to_char(g,'Mon') ELSE 'S'||ord END,'total',(SELECT count(*) FROM public.visitas v WHERE v.patrocinador_id=p_patrocinador_id AND NOT v.anulada AND v.fecha_hora>=g AND v.fecha_hora<least(g+paso,fin+interval '1 microsecond')),'nuevas',(SELECT count(*) FROM public.visitas v WHERE v.patrocinador_id=p_patrocinador_id AND NOT v.anulada AND v.tipo_cliente='nueva' AND v.fecha_hora>=g AND v.fecha_hora<least(g+paso,fin+interval '1 microsecond'))) ORDER BY g),'[]'::jsonb) INTO serie FROM generate_series(desde,fin,paso) WITH ORDINALITY AS t(g,ord);
RETURN resultado||jsonb_build_object('euros_por_euro_patrocinio',CASE WHEN cuota>0 THEN round(gasto/cuota,2) ELSE NULL END,'serie',serie,'objetivo_nuevas_90d',(SELECT count(*) FROM public.visitas WHERE patrocinador_id=p_patrocinador_id AND NOT anulada AND tipo_cliente='nueva' AND fecha_hora>=now()-interval '90 days' AND fecha_hora<=fin)); END $$;
CREATE FUNCTION public.stats_club(p_periodo text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pats jsonb; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; SELECT coalesce(jsonb_object_agg(id,public.stats_patrocinador(id,p_periodo)),'{}') INTO pats FROM public.patrocinadores; RETURN jsonb_build_object('socios_activos',(SELECT count(*) FROM public.socios WHERE estado='activa'),'activos_semana',(SELECT count(*) FROM public.socios WHERE estado='activa' AND ultima_apertura>=now()-interval '7 days'),'visitas',(SELECT coalesce(sum((value->>'visitas')::bigint),0) FROM jsonb_each(pats)),'nuevas_verificadas',(SELECT coalesce(sum((value->>'nuevas_verificadas')::bigint),0) FROM jsonb_each(pats)),'patrocinadores',pats,'bajas',(SELECT coalesce(jsonb_object_agg(motivo,n),'{}') FROM (SELECT motivo_baja AS motivo,count(*) AS n FROM public.patrocinadores WHERE NOT activo AND motivo_baja IS NOT NULL GROUP BY motivo_baja)t)); END $$;
REVOKE ALL ON FUNCTION public.enlazar_socio(text,text),public.entrar_negocio(text),public.identificar_socio(bigint),public.marcar_apertura(),public.crear_patrocinador(text,text,text,text,text,text,text,text,numeric),public.stats_patrocinador(uuid,text),public.stats_club(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enlazar_socio(text,text),public.entrar_negocio(text),public.identificar_socio(bigint),public.marcar_apertura(),public.crear_patrocinador(text,text,text,text,text,text,text,text,numeric),public.stats_patrocinador(uuid,text),public.stats_club(text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.socios,public.patrocinadores,public.ventajas,public.visitas,public.avisos,public.avisos_leidos,public.partidos;